const repoRoot = fileURLToPath(new URL("..", import.meta.url));
const scripts = JSON.parse(readFileSync(join(repoRoot, "package.json"), "utf8")).scripts;
// Only exact, independently confirmed stale references may be exempted here.
const KNOWN_STALE = [];
const failures = [];
let refs = 0;
const check = (source, ref, valid) => {
  refs++;
  if (!valid && !KNOWN_STALE.some((entry) => entry.source === source && entry.ref === ref)) {
    failures.push(`${source}: ${ref}`);
  }
};
const checkPath = (source, path) => {
  if (/^(?:tests|scripts)\/.+\.(?:mjs|js|ps1)$/.test(path) && !/[$`%{}]/.test(path)) {
    check(source, path, existsSync(join(repoRoot, path)));
  }
};
const tokens = (text) => [...text.matchAll(/"([^"\n]*)"|'([^'\n]*)'|([^\s]+)/g)]
  .map((match) => match[1] ?? match[2] ?? match[3]);
const scanCommands = (source, text) => {
  text = text.replace(/\$\{\{[\s\S]*?\}\}/g, "EXPRESSION");
  for (const match of text.matchAll(/\bnpm\s+run\s+([^\s;&|]+)/g)) {
    if (/^[\w:.-]+$/.test(match[1]) && !match[1].includes("EXPRESSION")) {
      check(source, `npm run ${match[1]}`, Object.hasOwn(scripts, match[1]));
    }
  }
  for (const match of text.matchAll(/(?:^|[\s;&|])node\s+([^\n;&|]+)/g)) {
    const args = tokens(match[1]);
    if (args[0] === "--test") {
      for (const path of args.slice(1)) checkPath(source, path);
    } else if (args[0]) {
      checkPath(source, args[0]);
    }
  }
  for (const match of text.matchAll(/-File\s+("[^"\n]*"|'[^'\n]*'|[^\s;&|]+)/gi)) {
    checkPath(source, tokens(match[1])[0]);
  }
};
for (const file of readdirSync(join(repoRoot, ".github", "workflows")).filter((file) => file.endsWith(".yml")).sort()) {
  const source = `.github/workflows/${file}`;
  scanCommands(source, readFileSync(join(repoRoot, source), "utf8"));
}
for (const [name, command] of Object.entries(scripts)) scanCommands(`package.json scripts.${name}`, command);
for (const file of readdirSync(join(repoRoot, "tests")).filter((file) => file.endsWith(".mjs")).sort()) {
  const source = `tests/${file}`;
  const text = readFileSync(join(repoRoot, source), "utf8");
  for (const match of text.matchAll(/\bjoin\(\s*repoRoot\s*,\s*["']tests["']\s*,\s*(["'])([^"'\n]+)\1\s*\)/g)) {
    if (!/[$`%{}]/.test(match[2])) {
      check(source, `tests/${match[2]}`, existsSync(join(repoRoot, "tests", match[2])));
    }
  }
}
if (failures.length) {
  console.error("litsan-script-references: missing references:\n" + failures.map((failure) => `- ${failure}`).join("\n"));
  process.exitCode = 1;
} else {
  console.log(`litsan-script-references: ok (${refs} refs)`);
}

